 'vocab-filter':()=>{ui.vocabSaved=!ui.vocabSaved;render()},'vocab-new':()=>modal('ADD EXPRESSION',vocabForm()),'vocab-star':el=>{const v=state.vocab.find(v=>v.id===el.dataset.id);v.saved=!v.saved;save();render();toast(v.saved?'已加入个人词库':'已取消收藏')},
 'vocab-review':el=>{const v=state.vocab.find(v=>v.id===el.dataset.id);modal('REVIEW CARD',`<h3 style="font:28px Georgia">${esc(v.word)}</h3><p lang="pt">${esc(v.sentence)}</p><details><summary>显示释义和用法</summary><p>${esc(v.zh)}<br>${esc(v.pt)}<br>${esc(v.collocation)}</p></details><div class="mt">${button('记住了 · 完成复习','vocab-reviewed',`data-id="${v.id}"`,'primary')}</div>`)},'vocab-reviewed':el=>{state.vocab.find(v=>v.id===el.dataset.id).reviews++;saved('本次复习已记录');close()},
 'translation-mode':el=>{ui.translationMode=el.dataset.value;render()},
 'quest-tab':el=>{ui.questTab=el.dataset.value;ui.questDate='';close();render()},'quest-category':el=>{ui.questCategory=el.dataset.value;render()},'quest-date':el=>{ui.questDate=el.dataset.value;render()},'mission-month':el=>moveMonth('missionMonth',Number(el.dataset.value)),
 'quest-new':el=>modal('NEW QUEST',questForm('',el.dataset.type||'DAILY')),'quest-edit':el=>modal('EDIT QUEST',questForm(el.dataset.id)),'quest-menu':el=>modal('QUEST DETAILS',questMenu(el.dataset.id)),
 'quest-toggle':el=>{const t=state.tasks.find(t=>String(t.id)===el.dataset.id);close();taskCompletion(t.id,!t.done)},'quest-delete':el=>confirmDelete('这条任务（历史 EXP 保留）',()=>{deleteQuest(state,el.dataset.id);saved('任务已删除');close()}),
