 'focus-range':el=>{ui.focusRange=el.dataset.value;render()},'focus-month':el=>moveMonth('focusMonth',Number(el.dataset.value)),'focus-day':el=>{ui.focusDate=el.dataset.value;render()},'focus-all':()=>{ui.focusAll=!ui.focusAll;render()},
 'focus-add':el=>{const f=el.closest('form'),field=f.elements.durationMinutes;field.value=Math.min(1440,Math.max(0,Number(field.value)||0)+Number(el.dataset.value));if(!f.dataset.id){state.focusDraft=Object.fromEntries(new FormData(f));save()}},
 'focus-menu':el=>modal('FOCUS SESSION',focusMenu(el.dataset.id)),'focus-edit':el=>modal('EDIT FOCUS SESSION',sessionForm(state.sessions.find(s=>s.id===el.dataset.id))),
